#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	// Must be a UPROPERTY: NewObject-created UObjects with only a raw C++ pointer
	// are invisible to GC and get purged, leaving a dangling pointer
	// (crash in AddPoints after "Collecting garbage", see Saved/Logs/PixelArena-shipping.log).
	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "AArenaGameMode::ScoreTracker was a raw C++ pointer (UArenaScoreTracker*) without UPROPERTY, so the UObject created via NewObject in BeginPlay was not referenced for garbage collection. The shipping log shows 'LogGarbage: Collecting garbage: 412 objects purged' at 21.05.13, then the next goal at 21.05.27 crashes with EXCEPTION_ACCESS_VIOLATION in UArenaScoreTracker::AddPoints called from AArenaGameMode::OnGoalScored: the tracker had been garbage-collected and the pointer was dangling. In the editor the object survives long enough / GC timing differs, so it appears to run fine. Fix: mark ScoreTracker as UPROPERTY() TObjectPtr<UArenaScoreTracker> in ArenaGameMode.h so GC keeps it alive (Hud and Palette already had UPROPERTY).",
  "no_colors_cause": "The palette data asset /Game/Data/Palettes/DA_Primary was never cooked into the packaged build. DefaultGame.ini packaging settings only cook the Arena map plus /Game/Data/Effects (bCookAll=False), and the palette is loaded at runtime via LoadObject with a string path, so the cooker cannot discover the reference. The shipping log shows 'LogStreaming: Error: Couldn't find file for package /Game/Data/Palettes/DA_Primary' and 'Palette is null, using fallback gray', hence the gray arena. In the editor all assets exist loose on disk, so it works there. Fix: add +DirectoriesToAlwaysCook=(Path=\"/Game/Data/Palettes\") to [/Script/UnrealEd.ProjectPackagingSettings] in Config/DefaultGame.ini."
}
